// Simplex noise or plasma noise function (you can use other noise functions if needed)

float noise(vec2 p) {

    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);

}

// Create kaleidoscopic pattern

vec2 kaleidoscope(vec2 uv, float slices) {

  //  uv -= 0.5;  // Center the coordinate system

    float angle = atan(uv.y, uv.x);

    float radius = length(uv);

    angle = mod(angle, 2.0 * 3.141592 / slices);  // Divide the space into slices

    angle = abs(angle - 3.141592 / slices); // Reflect the angle within each slice

    uv = vec2(cos(angle), sin(angle)) * radius;  // Map the angle back into the uv space

    uv += 0.5;  // Restore the original coordinate system

    return uv;

}

float fbm (in vec2 st) {

    float value = 0.0;

    float amplitude = .2;

    for (int i = 0; i < 6; i++) {

        value += amplitude * noise(st);

        st *= 2.;

        amplitude *= .2;

    }

    return value;

}

// Plasma noise function (an evolving noise)

float plasmaNoise(vec2 p, float t) {

    return sin(p.x * 10.0 + t) * cos(p.y * 10.0 + t);

}

mat2 rotate2d(float _angle){

    return mat2(cos(_angle),-sin(_angle),

                sin(_angle),cos(_angle));

}

vec2 rotate(vec2 _st, float _angle, vec2 _origin){

    _st -= _origin;

    _st = rotate2d(_angle) * _st;

    _st += _origin;

    return _st;

}

vec3 invertColor(vec3 _color){

    return vec3(1.0) - _color;

}

vec2 wave(vec2 uv, float frequency, float amplitude) {

    uv.y += sin(uv.x * frequency) * amplitude;

    return uv;

}

// Helper: Convert RGB to HSV

vec3 rgb2hsv(vec3 c) {

    float cMax = max(c.r, max(c.g, c.b));

    float cMin = min(c.r, min(c.g, c.b));

    float delta = cMax - cMin;

    float h = 0.0;

    if (delta > 0.0) {

        if (cMax == c.r) {

            h = mod((c.g - c.b) / delta, 6.0);

        } else if (cMax == c.g) {

            h = (c.b - c.r) / delta + 2.0;

        } else {

            h = (c.r - c.g) / delta + 4.0;

        }

        h /= 6.0;

    }

    float s = (cMax > 0.0) ? (delta / cMax) : 0.0;

    float v = cMax;

    return vec3(h, s, v);

}

// Helper: Convert HSV to RGB

vec3 hsv2rgb(vec3 c) {

    float h = c.x * 6.0;

    float s = c.y;

    float v = c.z;

    float c1 = v * s;

    float x = c1 * (1.0 - abs(mod(h, 2.0) - 1.0));

    float m = v - c1;

    vec3 rgb;

    if (0.0 <= h && h < 1.0) {

        rgb = vec3(c1, x, 0.0);

    } else if (1.0 <= h && h < 2.0) {

        rgb = vec3(x, c1, 0.0);

    } else if (2.0 <= h && h < 3.0) {

        rgb = vec3(0.0, c1, x);

    } else if (3.0 <= h && h < 4.0) {

        rgb = vec3(0.0, x, c1);

    } else if (4.0 <= h && h < 5.0) {

        rgb = vec3(x, 0.0, c1);

    } else {

        rgb = vec3(c1, 0.0, x);

    }

    return rgb + m;

}

float tri(float x) {

    return abs(fract(x) - 0.5) - .25;

}

vec2 toPolar(vec2 cartesian) {

    // Calculate the radius

    float radius = length(cartesian);

    // Calculate the angle (in radians)

    float angle = atan(cartesian.y, cartesian.x);

    // Return polar coordinates as a vec2 (radius, angle)

    return vec2(radius, angle);

}

vec2 toPolar(vec3 v) {

    float r = length(vec2(v.x, v.y)); // Radius in the XY-plane

    float theta = atan(v.y, v.x);     // Angle in the XY-plane

    return vec2(r, theta);

}

vec3 tricoord(vec2 cartesian) {

    // Define the scale for the triangular grid (size of each triangle)

    float scale = 1.0;

    // Convert Cartesian coordinates to scaled grid coordinates

    vec2 grid = cartesian / scale;

    // Basis vectors for an equilateral triangle grid

    vec2 basisX = vec2(1.0, 0.0);

    vec2 basisY = vec2(0.5, sqrt(3.0) / 2.0);

    // Compute the triangular coordinates in terms of barycentric components

    float u = dot(grid, basisX);

    float v = dot(grid, basisY);

    // Calculate the third barycentric coordinate

    float w = 1.0 - u - v;

    // Return barycentric coordinates as vec3(u, v, w)

    return vec3(u, v, w);

}

vec3 colorTriOne(vec3 baseColor) {

    // Convert base color from RGB to HSV

    vec3 hsv = rgb2hsv(baseColor);

    // Shift the hue slightly towards the next tertiary color

    // Add 30 degrees (1/12th of the hue circle) for the first tertiary color

    hsv.x = mod(hsv.x + (1.0 / 12.0), 1.0);

    // Convert back to RGB

    return hsv2rgb(hsv);

}

vec3 colorTriTwo(vec3 baseColor) {

    // Convert base color from RGB to HSV

    vec3 hsv = rgb2hsv(baseColor);

    // Shift the hue slightly towards the second tertiary color

    // Subtract 30 degrees (1/12th of the hue circle) for the second tertiary color

    hsv.x = mod(hsv.x - (1.0 / 12.0) + 1.0, 1.0);

    // Convert back to RGB

    return hsv2rgb(hsv);

}

vec2 hexagonalMapping(vec2 p) {

    float q = (sqrt(3.0) / 3.0) * p.x - (1.0 / 3.0) * p.y;

    float r = (2.0 / 3.0) * p.y;

    return vec2(q, r);

}

vec3 coordToRainbow(vec2 uv) {

    float t = uv.x + uv.y; // Combine uv coordinates

    return vec3(sin(t * 3.0), sin(t * 2.0 + 2.0), sin(t * 4.0 - 1.0)) * 0.5 + 0.5;

}

// Helper: Convert RGB to HSV

vec3 wiggle(vec3 i, float t) {

	return vec3(i.r*(1.+sin(t*1.1)),i.g*(1.+sin(t*1.2)),i.b*(1.+sin(t*1.3)));

	}

